    $("#kbbtn").onclick = () => { this._buzz(); const shown = $("#kb").classList.contains("on"); this._kbMode = shown ? "hide" : "show"; this._refresh(); if (!shown) setTimeout(() => kbi.focus(), 50); };   // toggles the text box, also while it opened by itself
