    ["touchmove", "pointermove"].forEach(t => strip.addEventListener(t, e => {
      const q = gpt(e), dx = Math.abs(q.clientX - gx), dy = Math.abs(q.clientY - gy);
      if (!gax && Math.max(dx, dy) > 6) gax = dx >= dy ? "h" : "v";
      if (gax === "h" && strip.scrollWidth > strip.clientWidth + 1) e.stopPropagation();
    }, { passive: true }));
    ["touchend", "touchcancel", "pointerup"].forEach(t => strip.addEventListener(t, e => { if (gax === "h" && strip.scrollWidth > strip.clientWidth + 1) e.stopPropagation(); }, { passive: true }));
    strip.addEventListener("wheel", e => { if (Math.abs(e.deltaX) > Math.abs(e.deltaY) && strip.scrollWidth > strip.clientWidth + 1) e.stopPropagation(); }, { passive: true });
